<body>
  <main class="quiz-shell">
    <section class="hero" aria-labelledby="quiz-title">
      <div class="eyebrow">Knowledge check</div>
      <h1 id="quiz-title">Computer Languages Quiz</h1>
      <p class="subtitle">Select all answers that apply for each question, then submit your choices.</p>
    </section>

    <form id="quiz-form">
      <div class="form-field">
        <div class="question-header">
          <h2 class="question-title">1. Which of these are programming languages?</h2>
          <p class="help-text">Pick every language you recognize from the list below.</p>
        </div>
        <div class="choices">
          <label class="choice"><input type="checkbox" name="q1" value="python" /><span>Python</span></label>
          <label class="choice"><input type="checkbox" name="q1" value="html" /><span>HTML</span></label>
          <label class="choice"><input type="checkbox" name="q1" value="javascript" /><span>JavaScript</span></label>
          <label class="choice"><input type="checkbox" name="q1" value="sql" /><span>SQL</span></label>
        </div>
      </div>

      <div class="form-field">
        <div class="question-header">
          <h2 class="question-title">2. Which of these are compiled languages?</h2>
        </div>
        <div class="choices">
          <label class="choice"><input type="checkbox" name="q2" value="c" /><span>C</span></label>
          <label class="choice"><input type="checkbox" name="q2" value="rust" /><span>Rust</span></label>
          <label class="choice"><input type="checkbox" name="q2" value="ruby" /><span>Ruby</span></label>
          <label class="choice"><input type="checkbox" name="q2" value="go" /><span>Go</span></label>
        </div>
      </div>

      <div class="form-field">
        <div class="question-header">
          <h2 class="question-title">3. Which of these are used to style web pages?</h2>
        </div>
        <div class="choices">
          <label class="choice"><input type="checkbox" name="q3" value="css" /><span>CSS</span></label>
          <label class="choice"><input type="checkbox" name="q3" value="scss" /><span>SCSS</span></label>
          <label class="choice"><input type="checkbox" name="q3" value="typescript" /><span>TypeScript</span></label>
          <label class="choice"><input type="checkbox" name="q3" value="less" /><span>Less</span></label>
        </div>
      </div>

      <div class="actions">
        <button type="submit">Submit Quiz</button>
      </div>
    </form>

    <div class="result" id="result" aria-live="polite"></div>
  </main>

  <script>
    const form = document.getElementById('quiz-form');
    const result = document.getElementById('result');

    const labels = {
      q1: 'Question 1',
      q2: 'Question 2',
      q3: 'Question 3'
    };

    form.addEventListener('submit', (event) => {
      event.preventDefault();

      const summary = Object.keys(labels).map((name) => {
        const selected = Array.from(form.querySelectorAll(`input[name="${name}"]:checked`))
          .map((input) => input.nextElementSibling.textContent);

        return `${labels[name]}: ${selected.length ? selected.join(', ') : 'No answers selected'}`;
      });

      result.innerHTML = `
        <strong>Your answers were submitted.</strong>
        <div>${summary.join('<br>')}</div>
      `;
      result.classList.add('show');
    });
  </script>
</body>
</html>
